package io.coolbox.pde;
import com.sun.jna.ptr.DoubleByReference;import io.coolbox.internal.ErrorBuffer;import io.coolbox.internal.Matrices;import io.coolbox.internal.NativeHandle;
/** Dense row-major matrix (Python: {@code pde.DenseMatrix}). */
public final class DenseMatrix extends NativeHandle {private static final PdeNative N=PdeNative.INSTANCE;private final int rows,cols;public DenseMatrix(int rows,int cols){super(N.coolbox_pde_matrix_new(rows,cols),N::coolbox_pde_matrix_free);this.rows=rows;this.cols=cols;}public DenseMatrix(double[][] values){this(values.length,Matrices.columns(values));for(int r=0;r<rows;r++)for(int c=0;c<cols;c++)set(r,c,values[r][c]);}public int rows(){return rows;}public int cols(){return cols;}public double get(int r,int c){DoubleByReference o=new DoubleByReference();ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_pde_matrix_get(handle(),r,c,o,e.pointer(),e.capacity()));return o.getValue();}public void set(int r,int c,double v){ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_pde_matrix_set(handle(),r,c,v,e.pointer(),e.capacity()));}public double[][] toArray(){double[] a=new double[rows*cols];ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_pde_matrix_copy(handle(),a,a.length,e.pointer(),e.capacity()));return Matrices.unflatten(a,rows,cols);}private double[][] solve(boolean stochastic,double alpha,double sigma,double dx,double dy,double dt,int steps,int seed){double[] out=new double[rows*cols];ErrorBuffer e=new ErrorBuffer();int status;if(stochastic)status=cols==1?N.coolbox_pde_solve_stochastic_heat_1d(handle(),alpha,sigma,dx,dt,steps,seed,out,e.pointer(),e.capacity()):N.coolbox_pde_solve_stochastic_heat_2d(handle(),alpha,sigma,dx,dy,dt,steps,seed,out,e.pointer(),e.capacity());else status=cols==1?N.coolbox_pde_solve_heat_1d(handle(),alpha,dx,dt,steps,out,e.pointer(),e.capacity()):N.coolbox_pde_solve_heat_2d(handle(),alpha,dx,dy,dt,steps,out,e.pointer(),e.capacity());e.check(status);return Matrices.unflatten(out,rows,cols);}public double[][] solveHeatEq(double alpha,double dx,double dt,int steps){return solve(false,alpha,0,dx,1,dt,steps,0);}public double[][] solveHeatEq2d(double alpha,double dx,double dy,double dt,int steps){return solve(false,alpha,0,dx,dy,dt,steps,0);}public double[][] solveStochasticHeatEq(double alpha,double sigma,double dx,double dt,int steps,int seed){return solve(true,alpha,sigma,dx,1,dt,steps,seed);}public double[][] solveStochasticHeatEq2d(double alpha,double sigma,double dx,double dy,double dt,int steps,int seed){return solve(true,alpha,sigma,dx,dy,dt,steps,seed);}}

